import { defineConfig } from 'vite'
import tailwindcss from '@tailwindcss/vite'
import { resolve, basename } from 'node:path'
import { readdirSync } from 'node:fs'
const root = import.meta.dirname

// Build entries are derived from the actual *.html files on disk (generated by
// scripts/gen-pages.mjs) so this list can't go stale when pages are renamed/added/removed.
const input = Object.fromEntries(
  readdirSync(root)
    .filter((f) => f.endsWith('.html') && f !== 'sitemap-current.html')
    .map((f) => [basename(f, '.html').replace(/-/g, '_'), resolve(root, f)]),
)

export default defineConfig({
  base: '/bancrofts-wireframes/',
  plugins: [tailwindcss()],
  build: {
    rollupOptions: { input },
  },
})
